<?php
declare(strict_types=1);
namespace App\Services\Finance;
use App\Models\Finance\{StudentInvoice,StudentPayment};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class PaymentService {public function record(StudentInvoice $invoice,array $data,int|null $actor=null):StudentPayment{return DB::transaction(function()use($invoice,$data,$actor){$invoice=StudentInvoice::lockForUpdate()->findOrFail($invoice->id);if(in_array($invoice->status,['cancelled','paid','draft'],true))throw ValidationException::withMessages(['invoice_id'=>'Tagihan tidak dapat dibayar.']);if((int)$data['amount']<=0||(int)$data['amount']>(int)$invoice->outstanding_amount)throw ValidationException::withMessages(['amount'=>'Nominal melebihi sisa tagihan.']);$payment=StudentPayment::create(['student_id'=>$invoice->student_id,'invoice_id'=>$invoice->id,'payment_number'=>'PAY-'.now()->format('Ymd').'-'.Str::upper(Str::random(8)),'payment_method'=>$data['payment_method'],'bank_provider'=>$data['payment_method']==='bri_briva'?'BRI':null,'bank_reference'=>$data['bank_reference']??null,'amount'=>$data['amount'],'paid_at'=>$data['paid_at'],'status'=>'succeeded','source'=>$data['source']??'manual','metadata'=>['note'=>$data['note']??null],'created_by'=>$actor]);$paid=(string)StudentPayment::where('invoice_id',$invoice->id)->where('status','succeeded')->sum('amount');$out=(string)max(0,(int)$invoice->total-(int)$paid);$invoice->update(['paid_amount'=>$paid,'outstanding_amount'=>$out,'status'=>(int)$out===0?'paid':'partial']);return $payment;});}}
